export class UnauthorizedError extends Error {
  constructor(detail = "Sign in to continue.") {
    super(detail);
  }
}

export const requireUser: RequestHandler = (_req, res, next) => {
  const principal = res.locals.principal;
  if (!principal) return next(new UnauthorizedError());
  if (principal.userId === null) return next(new ForbiddenError("This needs a signed-in user."));
  next();
};

import { randomUUID } from "node:crypto";
import argon2 from "argon2";

const options = {
  type: argon2.argon2id,
  memoryCost: 65_536,
  timeCost: 3,
  parallelism: 4,
} as const;

export function hashPassword(password: string): Promise<string> {
  return argon2.hash(password, options);
}

export function verifyPassword(stored: string, password: string): Promise<boolean> {
  return argon2.verify(stored, password);
}

export function needsRehash(stored: string): boolean {
  return argon2.needsRehash(stored, options);
}

