export function createAuthService({ users }: { users: UserRepository }) {
  return {
    async signUp(email: string, name: string, password: string): Promise<User> {
      return users.insert(email, name, await hashPassword(password));
    },

    async authenticate(email: string, password: string): Promise<User | null> {
      const user = await users.findByEmail(email);
      if (!user?.passwordHash) {
        await verifyPassword(DUMMY_HASH, password);
        return null;
      }
      if (!(await verifyPassword(user.passwordHash, password))) return null;
      if (needsRehash(user.passwordHash)) {
        await users.updatePasswordHash(user.id, await hashPassword(password));
      }
      return user;
    },
  };
}

export type AuthService = ReturnType<typeof createAuthService>;

const PgStore = connectPgSimple(session);

export function sessionCookie(production: boolean) {
  return {
    name: production ? "__Host-session" : "session",
    options: {
      httpOnly: true,
      secure: production,
      sameSite: "lax",
      path: "/",
      maxAge: 7 * 24 * 60 * 60 * 1000,
    },
  } as const;
}

export function sessions(pool: pg.Pool, secret: string, production: boolean) {
  const cookie = sessionCookie(production);
  return session({
    name: cookie.name,
    cookie: cookie.options,
    secret,
    store: new PgStore({ pool, tableName: "session" }),
    resave: false,
    saveUninitialized: false,
  });
}

export async function startSession(req: Request, userId: number): Promise<void> {
  await new Promise<void>((resolve, reject) =>
    req.session.regenerate((err) => (err ? reject(err) : resolve())),
  );
  req.session.userId = userId;
}

export async function endSession(req: Request): Promise<void> {
  await new Promise<void>((resolve, reject) =>
    req.session.destroy((err) => (err ? reject(err) : resolve())),
  );
}

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

export function sameOriginOnly(trustedOrigins: string[]): RequestHandler {
  const trusted = new Set(trustedOrigins);
  return (req, _res, next) => {
    if (SAFE_METHODS.has(req.method)) return next();

    const site = req.get("sec-fetch-site");
    if (site === "same-origin" || site === "none") return next();

    const origin = req.get("origin");
    if (origin && trusted.has(origin)) return next();
    if (!site && !origin) return next();

    next(new ForbiddenError("Cross-site requests can't change anything here."));
  };
}

export const ISSUER = "https://api.roombook.example";
export const AUDIENCE = "roombook-api";
export const ACCESS_TOKEN_SECONDS = 15 * 60;

export interface AccessClaims {
  id: number;
  role: Role;
  buildingId: number | null;
  scopes: string[];
}

export function createAccessTokens(base64urlSecret: string) {
  const key = Buffer.from(base64urlSecret, "base64url");

  return {
    issue(
      user: { id: number; role: Role; buildingId: number | null },
      scopes: readonly string[],
    ): Promise<string> {
      return new SignJWT({ role: user.role, building_id: user.buildingId, scope: scopes.join(" ") })
        .setProtectedHeader({ alg: "HS256", typ: "JWT" })
        .setSubject(String(user.id))
        .setIssuer(ISSUER)
        .setAudience(AUDIENCE)
        .setIssuedAt()
        .setExpirationTime(`${ACCESS_TOKEN_SECONDS}s`)
        .setJti(randomUUID())
        .sign(key);
    },

    async verify(token: string): Promise<AccessClaims> {
      const { payload } = await jwtVerify(token, key, {
        algorithms: ["HS256"],
        issuer: ISSUER,
        audience: AUDIENCE,
        requiredClaims: ["sub", "exp", "iat"],
      });
      return {
        id: Number(payload.sub),
        role: payload.role as Role,
        buildingId: (payload.building_id as number | null) ?? null,
        scopes: String(payload.scope ?? "")
          .split(" ")
          .filter(Boolean),
      };
    },
  };
}

export type AccessTokens = ReturnType<typeof createAccessTokens>;
